def canon(cs):
    pts = [(r,c) for r,c in cs]
    best = None
    m = np.array([[0,1],[1,0],[1,-1]])  # not used; do manual 8 dihedral
    base = np.array(pts, float)
    r0,c0 = base.min(0); base -= [r0,c0]
    gens = []
    cur = base
    for rot in range(4):
        for ref in (cur, cur*np.array([1,-1.])):
            rr = ref - ref.min(0)
            key = tuple(sorted(map(tuple, rr.astype(int))))
            gens.append(key)
        cur = np.stack([-cur[:,1], cur[:,0]],1).astype(float)
    return min(gens)

