import math
def canon2(cs):
    base = np.array(list(cs), float); r0,c0 = base.min(0); base -= [r0,c0]
    keys=[]; cur=base
    for rot in range(4):
        for ref in (cur, cur*np.array([1,-1.])):
            ref = ref - ref.min(0)
            keys.append(tuple(sorted(map(tuple, ref.astype(int)))))
        cur = np.stack([-cur[:,1], cur[:,0]],1).astype(float)
    return min(keys)

def run_rule(g, verbose=False):
    g = np.array(g)
    h,w = g.shape
    bg = np.bincount(g.flatten()).argmax()
    comps = comps_of(g, bg)
    colors = {}
    for c_,cs in comps: colors[c_]=colors.get(c_,0)+1
    ptr=None
    for c_,cs in comps:
        if len(cs)>=4 and colors[c_]==1:
            for (cr0,cc0) in cs:
                rowm={x for x in cs if x[0]==cr0}; colm={x for x in cs if x[1]==cc0}
                if set(cs)==rowm|colm and len(rowm)>=2 and len(colm)>=2:
                    ok=True; ptr=(c_,cs,(cr0,cc0)); break
            if ptr: break
    if not ptr: return None,'no pointer'
    pc, pcs, (cr,cc) = ptr
    sgn_r = 1 if any(r>cr for r,c in pcs if c==cc) else (-1 if any(r<cr for r,c in pcs if c==cc) else 0)
    sgn_c = 1 if any(c>cc for r,c in pcs if r==cr) else (-1 if any(c<cc for r,c in pcs if r==cr) else 0)
    ps = {(r,c) for r in range(h) for c in range(w) if (r-cr)*sgn_r>0 and (c-cc)*sgn_c>0}
    pocket_objs=[(c_,cs) for c_,cs in comps if set(cs)<=ps]
    if verbose:
        print('ptr',pc,'corner',(cr,cc),'arms',(sgn_r,sgn_c),'pocket objs:',
              [(c_,len(cs),(min(r for r,c in cs),min(c for r,c in cs))) for c_,cs in pocket_objs])
    if len(pocket_objs)!=1: return None,f'{len(pocket_objs)} pocket objs'
    oc, ocs = pocket_objs[0]
    key = canon2(ocs)
    grp = [(c_,cs) for c_,cs in comps if canon2(cs)==key]
    def cent(cs): return np.mean([r for r,c in cs]), np.mean([c for r,c in cs])
    orow,ocol = cent(ocs)
    def far(metric):
        best=None;bd=-1
        for c_,cs in grp:
            if c_==oc and set(cs)==set(ocs): continue
            r_,c_2 = cent(cs); d = metric(r_,c_2)
            if d>bd: bd=d; best=(c_,cs)
        return best
    return pc, far(lambda r,c: math.hypot(r-cr,c-cc)), far(lambda r,c: math.hypot(r-orow,c-ocol))

