def solve_with(g, ptrcs, cr, cc):
    g=np.array(g); h,w=g.shape; bg=np.bincount(g.flatten()).argmax()
    comps=comps_of(g,bg)
    sgn_r = 1 if any(r>cr for r,c in ptrcs if c==cc) else (-1 if any(r<cr for r,c in ptrcs if c==cc) else 0)
    sgn_c = 1 if any(c>cc for r,c in ptrcs if r==cr) else (-1 if any(c<cc for r,c in ptrcs if r==cr) else 0)
    if sgn_r==0 or sgn_c==0: return None
    ps={(r,c) for r in range(h) for c in range(w) if (r-cr)*sgn_r>0 and (c-cc)*sgn_c>0}
    pk=[(c_,cs) for c_,cs in comps if set(cs)<=ps]
    if len(pk)!=1: return ('pocket n',len(pk))
    oc,ocs=pk[0]; key=canon2(ocs)
    grp=[(c_,cs) for c_,cs in comps if canon2(cs)==key]
    def cent(cs): return np.mean([r for r,c in cs]),np.mean([c for r,c in cs])
    orow,ocol=cent(ocs)
    def far(metric):
        best=None;bd=-1
        for c_,cs in grp:
            if c_==oc and set(cs)==set(ocs): continue
            r_,c2=cent(cs); d=metric(r_,c2)
            if d>bd: bd=d; best=(c_,cs)
